(()=>{'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=null,model=null,busy=false,current='overview',filter={phase:'all',status:'all',team:'all',query:''};
const titles={overview:'Vue d’ensemble',groups:'Poules & classements',matches:'Tous les matchs',knockout:'Cup · Plate · Bowl',ranking:'Classement général',referees:'Arbitres',rules:'Règlement',sheets:'Tous les onglets',team:'Fiche équipe',referee:'Fiche arbitre'};
const rows=name=>(data.sheets[name]||[]).filter(r=>r.row>=6);
const value=(v,placeholder='—')=>v===null||v===undefined||v===''?placeholder:esc(v);
const validScore=v=>typeof v==='number' && Number.isFinite(v) && v>=0;
function normalize(){
 const teams=rows('Equipes').filter(r=>r.values[0]!=null).map(({row,values:v})=>({id:String(v[0]),group:v[1],name:v[3],country:v[4],comment:v[5],row}));
 const matches=[];
 rows('Matchs poules').filter(r=>r.values[0]!=null).forEach(({row,values:v})=>matches.push({id:'pool-'+v[0],sheet:'Matchs poules',row,code:'P'+String(v[0]).padStart(2,'0'),phase:'Poules',group:v[1],round:'Round Robin',a:v[2],b:v[3],sa:v[4],sb:v[5],forfeit:v[6],sourceStatus:v[7],pointsA:v[8],pointsB:v[9],done:validScore(v[4])&&validScore(v[5])||['H','A'].includes(v[6])}));
 ['Cup','Plate','Bowl'].forEach(phase=>rows(phase).filter(r=>r.values[0]!=null).forEach(({row,values:v})=>matches.push({id:phase.toLowerCase()+'-'+row,sheet:phase,row,code:phase+' · '+v[0],phase,round:v[1],seedA:v[2],a:v[3],seedB:v[4],b:v[5],sa:v[6],sb:v[7],tiebreak:v[8],winner:v[9],loser:v[10],done:Boolean(v[9])&&validScore(v[6])&&validScore(v[7])})));
 matches.forEach((m,i)=>{const start=(i%12)*3+Math.floor(i/12);m.refs=[0,1,2].map(k=>data.referees[(start+k)%data.referees.length]);});
 return {teams,matches};
}
function teamLink(name){const t=model.teams.find(t=>t.name===name);return t?`<a href="#team/${encodeURIComponent(t.id)}">${esc(name)}</a>`:value(name,'À déterminer');}
function refLinks(m){return m.refs.map(r=>`<a href="#referee/${r.id}">${esc(r.name)}</a>`).join('<span aria-hidden="true"> · </span>');}
function matchCard(m){return `<article class="match-card ${m.done?'finished':''}"><div class="match-top"><span>${esc(m.code)}${m.group?' · Poule '+esc(m.group):''}</span><span class="badge ${m.done?'complete':''}">${m.done?'Terminé':validScore(m.sa)&&validScore(m.sb)?'Départage attendu':'À jouer'}</span></div><div class="match-team"><strong>${teamLink(m.a)}</strong><b>${value(m.sa,'–')}</b></div><div class="match-team"><strong>${teamLink(m.b)}</strong><b>${value(m.sb,'–')}</b></div>${m.forfeit?`<p class="match-extra">Forfait : équipe ${m.forfeit==='H'?'A':'B'}</p>`:''}${m.tiebreak?`<p class="match-extra">Départage : équipe ${esc(m.tiebreak)}</p>`:''}<div class="refline"><span>ARBITRES · DÉMO</span><div>${refLinks(m)}</div></div><button class="match-open" data-match="${esc(m.id)}">Fiche du match <span>↗</span></button></article>`;}
function table(headers,body){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${body.join('')}</tbody></table></div>`;}
function stats(items){return `<div class="stats">${items.map(([n,l])=>`<div><b>${esc(n)}</b><span>${esc(l)}</span></div>`).join('')}</div>`;}
function heading(title,subtitle=''){return `<div class="section-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div></div>`;}
function overview(){const played=model.matches.filter(m=>m.done).length,remaining=model.matches.filter(m=>!m.done);
 return `<section class="competition-hero"><div><p class="eyebrow">20e ÉDITION · TOUCH MIXTE</p><h2>Chaque match compte.</h2><p>Suivez les équipes, les résultats et les désignations d’arbitres.</p><a class="light-button" href="#matches">Voir les rencontres ↗</a></div><div class="hero-number">${played}<span>/ ${model.matches.length} matchs terminés</span></div></section>${stats([[model.teams.length,'Équipes'],[new Set(model.teams.map(t=>t.group)).size,'Poules'],[played,'Matchs terminés'],[data.referees.length,'Arbitres fictifs']])}<div class="notice">Les résultats et classements proviennent du classeur. Les horaires et terrains ne sont pas renseignés. L’ordre affiché n’est pas un programme horaire.</div>${heading('Les poules','Toutes les équipes du Round Robin')}<div class="pool-grid">${[...new Set(model.teams.map(t=>t.group))].map(g=>`<section class="pool-card"><div class="pool-heading"><h3>Poule ${esc(g)}</h3><a href="#groups/${esc(g)}">Détails ↗</a></div>${model.teams.filter(t=>t.group===g).map(t=>`<a class="team-line" href="#team/${encodeURIComponent(t.id)}"><span>${esc(t.name)}</span><span>↗</span></a>`).join('')}</section>`).join('')}</div>${heading('Rencontres restant à jouer','Premières rencontres non terminées dans l’ordre du classeur')}<div class="match-grid">${remaining.slice(0,6).map(matchCard).join('')||'<p>Tous les matchs sont terminés.</p>'}</div>`;
}
function standings(g){const entries=rows('Classement poules').filter(r=>r.values[1]===g).sort((a,b)=>(a.values[12]??99)-(b.values[12]??99));return table(['#','Équipe','MJ','G','N','P','BP','BC','Diff.','Pts'],entries.map(({values:v})=>`<tr><td><b>${value(v[12])}</b></td><td>${teamLink(v[2])}</td>${v.slice(3,11).map((n,i)=>`<td${i===7?' class="points"':''}>${value(n)}</td>`).join('')}</tr>`));}
function groups(selected){const groupNames=[...new Set(model.teams.map(t=>t.group))];const g=groupNames.includes(selected)?selected:groupNames[0];return `<div class="pills">${groupNames.map(p=>`<a class="${p===g?'selected':''}" href="#groups/${esc(p)}">Poule ${esc(p)}</a>`).join('')}</div><section class="panel">${heading('Classement · Poule '+g,'MJ : matchs joués · G/N/P : gagnés/nuls/perdus · BP/BC : points marqués/encaissés')}${standings(g)}<p class="footnote">Barème du classeur : victoire 4 · nul 2 · défaite 1 · forfait 0. Les départages exceptionnels doivent être validés par l’organisation.</p></section>${heading('Round Robin · Poule '+g)}<div class="match-grid">${model.matches.filter(m=>m.group===g).map(matchCard).join('')}</div>`;}
function matchFilters(){return `<div class="filters"><label>Rechercher<input id="search" type="search" placeholder="Équipe, match ou arbitre…" value="${esc(filter.query)}"></label><label>Phase<select id="phase"><option value="all">Toutes les phases</option>${['Poules','Cup','Plate','Bowl'].map(p=>`<option ${filter.phase===p?'selected':''}>${p}</option>`).join('')}</select></label><label>État<select id="status"><option value="all">Tous les matchs</option><option value="pending" ${filter.status==='pending'?'selected':''}>À jouer</option><option value="done" ${filter.status==='done'?'selected':''}>Terminés</option></select></label><label>Équipe<select id="team-filter"><option value="all">Toutes les équipes</option>${model.teams.map(t=>`<option value="${esc(t.id)}" ${filter.team===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><p id="match-count" class="muted"></p><div id="match-list" class="match-grid"></div>`;}
function filteredMatches(){const name=model.teams.find(t=>t.id===filter.team)?.name,q=filter.query.toLocaleLowerCase();return model.matches.filter(m=>(filter.phase==='all'||m.phase===filter.phase)&&(filter.status==='all'||(filter.status==='done'?m.done:!m.done))&&(!name||m.a===name||m.b===name)&&[m.code,m.a,m.b,m.group,...m.refs.map(r=>r.name)].join(' ').toLocaleLowerCase().includes(q));}
function drawMatches(){const list=filteredMatches();$('#match-list').innerHTML=list.map(matchCard).join('')||'<p class="empty">Aucun match ne correspond à vos filtres.</p>';$('#match-count').textContent=`${list.length} rencontre${list.length===1?'':'s'}`;}
function knockout(selected){const division=['Cup','Plate','Bowl'].includes(selected)?selected:'Cup',matches=model.matches.filter(m=>m.phase===division);return `<div class="pills">${['Cup','Plate','Bowl'].map(d=>`<a class="${d===division?'selected':''}" href="#knockout/${d}">${d}</a>`).join('')}</div><p class="notice">Qualifications et progression suivent les formules du classeur. Les affiches non déterminées restent en attente. Voir le règlement avant de figer les rencontres.</p><div class="bracket">${[['Quarts de finale',matches.slice(0,4)],['Demi-finales',matches.slice(4,6)],['Finale & 3e place',matches.slice(8,10)]].map(([label,list])=>`<section class="bracket-column"><h2>${label}</h2>${list.map(matchCard).join('')}</section>`).join('')}</div>${heading('Matchs de classement','Places 5 à 8 de la division '+division)}<div class="match-grid">${[...matches.slice(6,8),...matches.slice(10,12)].map(matchCard).join('')}</div>`;}
function ranking(selected){const final=selected==='final';return `<div class="pills"><a href="#ranking/seeding" class="${!final?'selected':''}">Ranking après les poules</a><a href="#ranking/final" class="${final?'selected':''}">Classement final</a></div><section class="panel">${heading(final?'Classement final · 1 à 24':'Ranking · 1 à 24',final?'Les places sont déterminées par les matchs de classement.':'Les premiers de poule, puis les deuxièmes, troisièmes et quatrièmes.')}${final?table(['Position','Division','Équipe','Match déterminant','Joués','État'],rows('Classement final').map(({values:v})=>`<tr><td class="rank">${value(v[0])}</td><td><span class="badge">${value(v[1])}</span></td><td>${teamLink(v[2])}</td>${v.slice(3,6).map(x=>`<td>${value(x)}</td>`).join('')}</tr>`)):table(['Rang','Division','Équipe','Poule','Rang poule','Points','Joués','État'],rows('Ranking 1-24').map(({values:v})=>`<tr><td class="rank">${value(v[0])}</td><td><span class="badge">${value(v[1])}</span></td><td>${teamLink(v[2])}</td>${[v[3],v[4],v[5],v[8],v[9]].map(x=>`<td>${value(x)}</td>`).join('')}</tr>`))}<p class="footnote">Classements issus du Sheet. L’ordre technique utilisé pour une égalité persistante ne remplace pas la validation des critères sportifs.</p></section>`;}
function referees(){return `<p class="notice">36 arbitres fictifs, nommés d’après des acteurs. Trois arbitres par match. Cette répartition de démonstration n’est pas un planning validé : horaires, disponibilités et éventuels rôles de joueur restent à intégrer.</p><label class="ref-search">Rechercher un arbitre<input id="ref-search" type="search" placeholder="Nom de l’acteur…"></label><div class="ref-grid" id="ref-list">${refereeCards('')}</div>`;}
function refereeCards(q){return data.referees.filter(r=>r.name.toLocaleLowerCase().includes(q.toLocaleLowerCase())).map(r=>{const matches=model.matches.filter(m=>m.refs.some(x=>x.id===r.id));return `<a class="ref-card" href="#referee/${r.id}"><span class="avatar">${esc(r.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><div><h3>${esc(r.name)}</h3><span>${matches.length} matchs · arbitre fictif</span></div><b>↗</b></a>`;}).join('')||'<p class="empty">Aucun arbitre trouvé.</p>';}
function referee(id){const r=data.referees.find(r=>r.id===id);if(!r)return '<p class="empty">Arbitre introuvable.</p>';const matches=model.matches.filter(m=>m.refs.some(x=>x.id===id));return `<a class="back" href="#referees">← Tous les arbitres</a><section class="profile-banner"><span class="avatar">${esc(r.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><div><p class="eyebrow">ARBITRE FICTIF · DÉMONSTRATION</p><h2>${esc(r.name)}</h2><p>${matches.length} rencontres attribuées · horaires à définir</p></div></section><div class="match-grid">${matches.map(matchCard).join('')}</div>`;}
function team(id){const t=model.teams.find(t=>t.id===id);if(!t)return '<p class="empty">Équipe introuvable.</p>';const matches=model.matches.filter(m=>m.a===t.name||m.b===t.name);return `<a class="back" href="#groups/${esc(t.group)}">← Poule ${esc(t.group)}</a><section class="profile-banner"><div><p class="eyebrow">POULE ${esc(t.group)} · TOUCH IN PARIS 2027</p><h2>${esc(t.name)}</h2><p>${value(t.country,'')}${t.comment?' · '+esc(t.comment):''}</p></div></section>${stats([[matches.length,'Rencontres déterminées'],[matches.filter(m=>m.done).length,'Terminées'],[matches.filter(m=>!m.done).length,'À jouer']])}<p class="muted">Les rencontres de phases finales apparaissent lorsque les adversaires sont déterminés dans le classeur.</p><div class="match-grid">${matches.map(matchCard).join('')}</div>`;}
function rules(){return `<section class="panel rules">${heading('Règlement & hypothèses du classeur','Texte repris de l’onglet Reglement. Les points à confirmer sont conservés.')}<ol>${rows('Reglement').map(r=>`<li>${esc(r.values.filter(v=>v!=null).join(' '))}</li>`).join('')}</ol></section>`;}
function sheets(selected){const names=Object.keys(data.sheets),name=names.includes(selected)?selected:names[0],source=data.sheets[name],headers=source.find(r=>r.row===5)?.values||[],width=Math.max(...source.map(r=>r.values.length));return `<div class="notice">Vue intégrale des valeurs des ${names.length} onglets, y compris les indicateurs techniques. Les calculs restent exécutés dans Google Sheets.</div><label class="sheet-picker">Onglet<select id="sheet-select">${names.map(n=>`<option ${n===name?'selected':''}>${esc(n)}</option>`).join('')}</select></label><section class="panel">${heading(name)}${table(['Ligne',...Array.from({length:width},(_,i)=>headers[i]||String.fromCharCode(65+i))],source.filter(r=>r.row!==5).map(r=>`<tr><td>${r.row}</td>${Array.from({length:width},(_,i)=>`<td>${value(r.values[i],'')}</td>`).join('')}</tr>`))}</section>`;}
function render(){if(!model)return;const [view,encoded]=location.hash.slice(1).split('/');let id;try{id=decodeURIComponent(encoded||'');}catch{id='';}current=titles[view]?view:'overview';$('#page-title').textContent=titles[current];document.querySelectorAll('[data-view]').forEach(a=>{const active=a.dataset.view===current||(current==='referee'&&a.dataset.view==='referees')||(current==='team'&&a.dataset.view==='groups');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#content').innerHTML=({overview,groups,matches:matchFilters,knockout,ranking,referees,rules,sheets,team,referee}[current])(id);if(current==='matches')drawMatches();}
function detail(id){const m=model.matches.find(m=>m.id===id);if(!m)return;$('#match-detail').innerHTML=`<p class="eyebrow">${esc(m.phase)} · ${esc(m.round)}</p><h2>${esc(m.code)}</h2><div class="detail-score"><span>${teamLink(m.a)}</span><b>${value(m.sa,'–')} : ${value(m.sb,'–')}</b><span>${teamLink(m.b)}</span></div><dl><dt>État</dt><dd>${m.done?'Terminé':'À jouer / à confirmer'}</dd><dt>Terrain / horaire</dt><dd>Non renseignés</dd>${m.winner?`<dt>Vainqueur</dt><dd>${esc(m.winner)}</dd>`:''}${m.forfeit?`<dt>Forfait</dt><dd>Équipe ${m.forfeit==='H'?'A':'B'}</dd>`:''}${m.tiebreak?`<dt>Départage</dt><dd>Équipe ${esc(m.tiebreak)}</dd>`:''}<dt>Source</dt><dd>${esc(m.sheet)} · ligne ${m.row}</dd></dl><h3>Les trois arbitres</h3><p class="muted">Noms fictifs pour la démonstration</p><div class="detail-refs">${m.refs.map(r=>`<a href="#referee/${r.id}">${esc(r.name)} <span>Voir ses matchs ↗</span></a>`).join('')}</div>`;$('#match-dialog').showModal();}
async function refresh(){if(busy)return;busy=true;$('#refresh').disabled=true;try{const response=await fetch('data.php',{credentials:'same-origin',cache:'no-store'});if(response.status===401){location.reload();return;}if(!response.ok)throw Error('Données momentanément indisponibles.');const next=await response.json();data=next;model=normalize();$('#sync-status').textContent=`${next.mode==='snapshot'?'Copie initiale':'Synchronisé'} · ${new Date(next.updatedAt).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'medium'})}`;$('#warning').hidden=!next.warning;$('#warning').textContent=next.warning||'';const focused=document.activeElement;if(!focused?.matches('input,select')&&!$('#match-dialog').open)render();}catch(e){$('#warning').hidden=false;$('#warning').textContent='Actualisation indisponible. '+(model?'Les dernières données restent affichées.':'Rechargez la page pour réessayer.');$('#sync-status').textContent='Connexion à rétablir';}finally{busy=false;$('#refresh').disabled=false;}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-match]');if(button)detail(button.dataset.match);if(e.target.closest('.close'))$('#match-dialog').close();if(e.target.closest('#match-dialog a'))$('#match-dialog').close();});
document.addEventListener('input',e=>{if(e.target.id==='search'){filter.query=e.target.value;drawMatches();}if(e.target.id==='ref-search')$('#ref-list').innerHTML=refereeCards(e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='phase')filter.phase=e.target.value;if(e.target.id==='status')filter.status=e.target.value;if(e.target.id==='team-filter')filter.team=e.target.value;if(['phase','status','team-filter'].includes(e.target.id))drawMatches();if(e.target.id==='sheet-select')location.hash='sheets/'+encodeURIComponent(e.target.value);});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});$('#refresh').addEventListener('click',refresh);refresh();setInterval(()=>{if(!document.hidden)refresh();},60000);
})();
